// Function to validate basic email pattern
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Function to convert MM-DD-YYYY to YYYY-MM-DD
function formatDate(dateStr) {
  if (!dateStr || dateStr.includes('INVALID')) return null;
  const parts = dateStr.split('-');
  if (parts.length === 3) {
    const [month, day, year] = parts;
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }
  return dateStr;
}

const cleanedItems = [];

for (const item of $input.all()) {
  try {
    // 1. Extract and parse the nested JSON string from 'text'
    const rawData = typeof item.json.text === 'string' 
      ? JSON.parse(item.json.text) 
      : item.json;

    // 2. Clean and structure the record
    const cleanRecord = {
      student_id: rawData.Student_ID ? rawData.Student_ID.trim() : null,
      first_name: rawData.First_Name ? rawData.First_Name.trim() : null,
      last_name: rawData.Last_Name ? rawData.Last_Name.trim() : null,

      // Clean Email: set to null if marked INVALID or invalid format
      email: isValidEmail(rawData.Email) ? rawData.Email.trim().toLowerCase() : null,

      // Clean Phone: convert to string, format digits
      phone: rawData.Phone ? String(rawData.Phone).replace(/\D/g, '') : null,

      course: rawData.Course ? rawData.Course.trim() : null,

      // Clean Fee_Paid: convert "yes"/"no" or string to boolean
      fee_paid: String(rawData.Fee_Paid).toLowerCase().trim() === 'yes',

      city: rawData.City ? rawData.City.trim() : null,

      // Format Date to YYYY-MM-DD
      enrolled_date: formatDate(rawData.Enrolled_Date)
    };

    cleanedItems.push({ json: cleanRecord });
  } catch (error) {
    // Handle parsing errors gracefully
    cleanedItems.push({
      json: {
        error: "Failed to parse record",
        raw_text: item.json.text
      }
    });
  }
}

return cleanedItems;
